  "content": "1|import { useMutation, useQuery } from '@tanstack/react-query';
2|import type { BaseInfoRow } from '../contracts/base-info/types';
3|import type { TreeDropPosition } from '../../types/tree';
4|import {
5|  apiDelete,
6|  apiGet,
7|  apiPost,
8|  apiPut,
9|  type ApiListResponse,
10|  type ApiMutationResponse,
11|} from '../client';
12|
13|export type BaseInfoChildrenParams = {
14|  lang: string;
15|  root: string;
16|  parentId?: string | null;
17|};
18|
19|export type BaseInfoNodePayload = {
20|  parentId?: string;
21|  childDigits?: number;
22|  title?: string;
23|  titleEn?: string;
24|  titleFa?: string;
25|  titleAr?: string;
26|  shortName?: string;
27|  note?: string;
28|  noteEn?: string;
29|  noteFa?: string;
30|  noteAr?: string;
31|  viewOrder?: number;
32|  value?: number;
33|  metadata?: string;
34|  uiColor?: string;
35|  uiHtml?: string;
36|  isActive?: boolean;
37|};
38|
39|export type BaseInfoMovePayload = {
40|  targetId: string | null;
41|  position: TreeDropPosition;
42|};
43|
44|export const baseInfoQueryKeys = {
45|  all: ['base-info'] as const,
46|  children: (params: BaseInfoChildrenParams) => [...baseInfoQueryKeys.all, 'children', params] as const,
47|};
48|
49|const assertListSuccess = (data: ApiListResponse, response: Response, fallback: string) => {
50|  if (!response.ok) {
51|    throw new Error(`Server returned ${response.status} for children endpoint.`);
52|  }
53|  if (!data.success) {
54|    throw new Error(typeof data.error === 'string' ? data.error : fallback);
55|  }
56|};
57|
58|const assertMutationSuccess = (
59|  data: ApiMutationResponse,
60|  response: Response,
61|  fallback: string,
62|) => {
63|  if (!response.ok || !data.success) {
64|    throw new Error(typeof data.error === 'string' ? data.error : `${fallback} (HTTP ${response.status}).`);
65|  }
66|};
67|
68|export async function fetchBaseInfoChildren(params: BaseInfoChildrenParams): Promise<BaseInfoRow[]> {
69|  const searchParams = new URLSearchParams();
70|  if (params.lang) searchParams.set('lang', params.lang);
71|  if (params.root.trim()) searchParams.set('root', params.root.trim());
72|  if (params.parentId) searchParams.set('parentId', params.parentId);
73|  searchParams.set('includeInactive', 'true');
74|
75|  const { data, response } = await apiGet<ApiListResponse>(`/api/base-info/children?${searchParams.toString()}`);
76|  assertListSuccess(data, response, 'Failed to load nodes.');
77|  return (data.items || []) as BaseInfoRow[];
78|}
