80|export async function createBaseInfoNode(body: BaseInfoNodePayload): Promise<ApiMutationResponse> {
81|  const { data, response } = await apiPost<ApiMutationResponse>('/api/base-info', body);
82|  if (!response.ok || !data.success) {
83|    throw new Error(typeof data.error === 'string' ? data.error : 'Failed to create node.');
84|  }
85|  return data;
86|}
87|
88|export async function updateBaseInfoNode(id: string, body: BaseInfoNodePayload): Promise<ApiMutationResponse> {
89|  const { data, response } = await apiPut<ApiMutationResponse>(`/api/base-info/${encodeURIComponent(id)}`, body);
90|  if (!response.ok || !data.success) {
91|    throw new Error(typeof data.error === 'string' ? data.error : 'Failed to update node.');
92|  }
93|  return data;
94|}
95|
96|export async function deleteBaseInfoNode(id: string): Promise<void> {
97|  const { data, response } = await apiDelete<ApiMutationResponse>(`/api/base-info/${encodeURIComponent(id)}`);
98|  assertMutationSuccess(data, response, 'Failed to delete node');
99|}
100|
101|export async function moveBaseInfoNode(id: string, body: BaseInfoMovePayload): Promise<void> {
102|  const { data, response } = await apiPost<ApiMutationResponse>(
103|    `/api/base-info/${encodeURIComponent(id)}/move`,
104|    body,
105|  );
106|  assertMutationSuccess(data, response, 'Failed to move node');
107|}
108|
109|export function useBaseInfoChildrenQuery(
110|  params: BaseInfoChildrenParams,
111|  enabled = true,
112|) {
113|  return useQuery({
114|    queryKey: baseInfoQueryKeys.children(params),
115|    queryFn: () => fetchBaseInfoChildren(params),
116|    enabled,
117|  });
118|}
